<?php require __DIR__.'/../app/bootstrap.php';require_login();$u=current_user($pdo);$network=trim($_GET['network']??'');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$planId=(int)($_POST['plan_id']??0);$phone=preg_replace('/\D+/','',$_POST['phone']??'');$s=$pdo->prepare('SELECT * FROM data_plans WHERE id=? AND active=1');$s->execute([$planId]);$plan=$s->fetch();if(!$plan||!preg_match('/^(?:0|234)[789][01]\d{8}$/',$phone)){flash('error','Select a valid data plan and Nigerian phone number.');header('Location:/buy-data.php');exit;}if(str_starts_with($phone,'234'))$phone='0'.substr($phone,3);try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT balance FROM wallets WHERE user_id=? FOR UPDATE');$s->execute([$u['id']]);$wallet=$s->fetch();if(!$wallet||$wallet['balance']<$plan['sell_price'])throw new RuntimeException('Insufficient wallet balance.');$ref='DATA-'.date('YmdHis').'-'.bin2hex(random_bytes(4));$pdo->prepare('UPDATE wallets SET balance=balance-? WHERE user_id=?')->execute([$plan['sell_price'],$u['id']]);$pdo->prepare('INSERT INTO wallet_transactions(user_id,type,amount,reference,description,status) VALUES(?,?,?,?,?,?)')->execute([$u['id'],'debit',$plan['sell_price'],$ref,'Data purchase - '.$plan['name'],'successful']);$wtid=$pdo->lastInsertId();$pdo->prepare('INSERT INTO data_transactions(user_id,wallet_transaction_id,network,phone,plan,provider_plan_id,amount,cost_amount,status) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$u['id'],$wtid,$plan['network'],$phone,$plan['name'],$plan['provider_plan_id'],$plan['sell_price'],$plan['cost_price'],'pending']);$dtid=$pdo->lastInsertId();$pdo->commit();try{$provider=new VtuProvider($config['vtu']);$result=$provider->purchaseData($plan['network'],$phone,$plan['provider_plan_id'],$ref);$ok=(($result['code']??'')==='success')||(($result['status']??'')==='success')||(($result['success']??false)===true);if($ok){$providerRef=$result['data']['order_id']??$result['data']['reference']??$result['reference']??null;$pdo->prepare('UPDATE data_transactions SET status="successful",provider_reference=? WHERE id=?')->execute([$providerRef,$dtid]);flash('success','Data purchase successful.');}else{throw new RuntimeException($result['message']??'Data provider rejected the order.');}}catch(Throwable $ex){$pdo->beginTransaction();$pdo->prepare('UPDATE data_transactions SET status="reversed" WHERE id=?')->execute([$dtid]);$pdo->prepare('UPDATE wallets SET balance=balance+? WHERE user_id=?')->execute([$plan['sell_price'],$u['id']]);$pdo->prepare('INSERT INTO wallet_transactions(user_id,type,amount,reference,description,status) VALUES(?,?,?,?,?,?)')->execute([$u['id'],'credit',$plan['sell_price'],'REV-'.$ref,'Data purchase reversal','successful']);$pdo->commit();flash('error','Data purchase failed; your wallet was reversed.');}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());}header('Location:/buy-data.php');exit;}
$plans=$pdo->query('SELECT * FROM data_plans WHERE active=1 ORDER BY network,price')->fetchAll();$group=[];foreach($plans as $p)$group[$p['network']][]=$p;require __DIR__.'/../app/layout.php';header_html('Buy Data');?><div class="card"><div class="section-head"><div><p class="eyebrow">Data bundles</p><h2>Buy Data</h2></div><a class="btn secondary" href="/wallet.php">Fund wallet</a></div><?php if(!$plans):?><div class="empty">No active data plans yet. Ask the administrator to sync plans from the VTU provider.</div><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>Network</label><select id="network" required><?php foreach(array_keys($group) as $n):?><option value="<?=e($n)?>" <?=strcasecmp($network,$n)===0?'selected':''?>><?=e(strtoupper($n))?></option><?php endforeach;?></select></div><div class="field"><label>Phone number</label><input name="phone" inputmode="numeric" placeholder="08012345678" maxlength="11" required></div><div class="field"><label>Data plan</label><select name="plan_id" id="plan" required></select></div><div class="plan-price" id="price"></div><button class="btn" type="submit">Buy Data</button></form><?php endif;?></div><?php if($plans):?><script>const plans=<?=json_encode($group)?>;const n=document.querySelector('#network'),p=document.querySelector('#plan'),price=document.querySelector('#price');function load(){p.innerHTML='';(plans[n.value]||[]).forEach(x=>{const o=document.createElement('option');o.value=x.id;o.textContent=x.name+' — ₦'+Number(x.price).toLocaleString();o.dataset.price=x.price;p.appendChild(o)});price.textContent=p.options.length?'You will be charged ₦'+Number(p.options[0].dataset.price).toLocaleString():''}n.addEventListener('change',load);p.addEventListener('change',()=>price.textContent='You will be charged ₦'+Number(p.options[p.selectedIndex].dataset.price).toLocaleString());load();</script><?php endif;?><?php footer_html();
